#!/usr/bin/env python3
"""Plot CSV results generated by nsbiot_comparison_experiments.py.

Creates individual, publication-friendly figure files without changing the
recorded numerical data. Requires matplotlib (not required by dry-run).
"""
import argparse
import csv
import math
from collections import defaultdict
from pathlib import Path


def load(path):
    if not path.exists():
        return []
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def num(row,key,default=None):
    try:
        v=float(row.get(key,''))
        return v if math.isfinite(v) else default
    except (ValueError,TypeError):
        return default


def plot_main(folder):
    import matplotlib.pyplot as plt
    runs=load(folder/'runs.csv')
    energies=load(folder/'energy.csv')
    thresh=load(folder/'empirical_thresholds.csv')
    files=[]

    # Hold mesh and time step fixed: direct method-vs-method energy curves.
    for study in ('energy','stability'):
        data=[r for r in energies if r['study']==study and r.get('label')=='baseline']
        if not data: continue
        nm=min(int(r['nm']) for r in data)
        dts=sorted({float(r['dt']) for r in data if int(r['nm'])==nm},reverse=True)
        if not dts: continue
        dt=dts[0]
        data=[r for r in data if int(r['nm'])==nm and math.isclose(float(r['dt']),dt,abs_tol=1e-13)]
        groups=defaultdict(list)
        for r in data: groups[r['scheme']].append((float(r['t']),float(r['energy'])))
        if len(groups)<2:continue
        fig,ax=plt.subplots()
        for scheme,vals in groups.items():
            vals.sort()
            E1=vals[0][1]
            if E1>0:
                ax.plot([x for x,e in vals],[e/E1 for x,e in vals],
                        marker='o',markersize=2,label=scheme.replace('_',' '))
        ax.set(xlabel='Time',ylabel='BDF2 energy / initial BDF2 energy',
               title=f'{study}: n={nm}, dt={dt:g}, no volume forcing')
        ax.legend();ax.grid(alpha=.25)
        target=folder/f'energy_{study}_n{nm}.png'
        fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)

    # Convergence curves, one variable per figure.
    for study,xkey in (('temporal','dt'),('spatial','h')):
        data=[r for r in runs if r.get('study')==study and r.get('status')=='ok'
              and r.get('label')=='baseline']
        if not data: continue
        if study=='temporal':
            nm=max(int(r['nm']) for r in data)
            data=[r for r in data if int(r['nm'])==nm]
        for field in ('err_u','err_p','err_eta','err_xi','err_phi'):
            groups=defaultdict(list)
            for r in data:
                x=num(r,xkey); y=num(r,field)
                if x is not None and y is not None and x>0 and y>0:
                    groups[r['scheme']].append((x,y))
            if not groups: continue
            fig,ax=plt.subplots()
            for scheme,vals in groups.items():
                vals.sort()
                ax.loglog([t[0] for t in vals],[t[1] for t in vals],
                          marker='o',label=scheme.replace('_',' '))
            ax.set(xlabel='Time step' if study=='temporal' else 'Mesh spacing 1/n',
                   ylabel=field,title=f'{study.title()} convergence: {field}')
            ax.legend();ax.grid(alpha=.3,which='both')
            target=folder/f'{study}_{field}.png'
            fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)

    if thresh:
        groups=defaultdict(list)
        for r in thresh:
            h=num(r,'h');dt=num(r,'largest_passing_dt_tested')
            if h and dt:groups[r['scheme']].append((h,dt))
        if groups:
            fig,ax=plt.subplots()
            for scheme,vals in groups.items():
                vals.sort()
                ax.loglog([x for x,y in vals],[y for x,y in vals],marker='o',
                          label=f'{scheme.replace("_"," ")} (tested criterion)')
            anchors=[(x,y) for v in groups.values() for x,y in v]
            x0,y0=anchors[0]
            xs=sorted(set(x for x,y in anchors))
            if len(xs)>1:
                ax.loglog(xs,[y0*x/x0 for x in xs],'--',alpha=.6,label='slope 1 reference')
                ax.loglog(xs,[y0*(x/x0)**2 for x in xs],':',alpha=.7,label='slope 2 reference')
            ax.set(xlabel='Mesh spacing 1/n',ylabel='Largest tested step meeting growth criterion',
                   title='Empirical finite-horizon energy criterion (not sharp CFL)')
            ax.legend();ax.grid(alpha=.3,which='both')
            target=folder/'empirical_thresholds.png'
            fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)

    costs=[r for r in runs if r.get('study')=='cost' and r.get('status')=='ok']
    for field in ('err_u','err_eta'):
        if not costs:break
        groups=defaultdict(list)
        for r in costs:
            err=num(r,field);wall=num(r,'wall_s')
            if err and wall and err>0 and wall>0:groups[r['scheme']].append((wall,err))
        if not groups:continue
        fig,ax=plt.subplots()
        for scheme,vals in groups.items():
            vals.sort()
            ax.loglog([x for x,y in vals],[y for x,y in vals],marker='o',
                      label=scheme.replace('_',' '))
        ax.set(xlabel='Sequential measured wall time (seconds)',ylabel=field,
               title=f'Cost vs accuracy ({field})')
        ax.grid(alpha=.3,which='both');ax.legend()
        target=folder/f'cost_{field}.png'
        fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)

    parameters=[r for r in runs if r.get('study')=='parameters' and r.get('status')=='ok']
    by_parameter=defaultdict(lambda:defaultdict(list))
    for r in parameters:
        label=r.get('label','')
        if '=' not in label:continue
        key,value=label.split('=',1)
        try:value=float(value)
        except ValueError:continue
        metric=num(r,'peak_energy_ratio')
        if metric is not None and metric>0:
            by_parameter[key][r['scheme']].append((value,metric))
    for param,group in by_parameter.items():
        fig,ax=plt.subplots()
        for scheme,vals in group.items():
            vals.sort()
            ax.semilogx([x for x,y in vals],[y for x,y in vals],marker='o',
                        label=scheme.replace('_',' '))
        ax.set(xlabel=param,ylabel='Maximum E / initial E',
               title=f'Homogeneous parameter sensitivity: {param}')
        ax.grid(alpha=.3);ax.legend()
        target=folder/f'parameter_{param}.png'
        fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)
    # The peak includes the initial energy and can equal one throughout a scan.
    # Also show terminal decay, using the recorded raw energies unchanged.
    final_groups=defaultdict(lambda:defaultdict(list))
    for r in parameters:
        label=r.get('label','')
        if '=' not in label:continue
        key,value=label.split('=',1)
        initial=num(r,'energy_initial'); final=num(r,'energy_final')
        try:value=float(value)
        except ValueError:continue
        if initial is not None and initial>0 and final is not None and final>=0:
            final_groups[key][r['scheme']].append((value,final/initial))
    for param,group in final_groups.items():
        fig,ax=plt.subplots()
        for scheme,vals in group.items():
            vals.sort()
            ax.semilogx([x for x,y in vals],[y for x,y in vals],marker='o',
                        label=scheme.replace('_',' '))
        ax.set(xlabel=param,ylabel='Final E / initial E',
               title=f'Homogeneous terminal energy sensitivity: {param}')
        ax.grid(alpha=.3);ax.legend()
        target=folder/f'parameter_final_{param}.png'
        fig.savefig(target,dpi=180,bbox_inches='tight');plt.close(fig);files.append(target)
    if not files:
        print('No completed comparison data found. Run the experiment driver with FEniCS first.')
    else:
        for f in files:print(f)


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('results_dir',type=Path)
    a=p.parse_args()
    plot_main(a.results_dir)
